apiVersion: batch/v1
kind: Job
metadata:
  name: {{ include "product-bulk-creator.fullname" . }}
  labels:
    {{- include "product-bulk-creator.labels" . | nindent 4 }}
spec:
  backoffLimit: {{ .Values.job.backoffLimit }}
  ttlSecondsAfterFinished: {{ .Values.job.ttlSecondsAfterFinished }}
  template:
    metadata:
      annotations:
        {{- with .Values.podAnnotations }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      labels:
        {{- include "product-bulk-creator.selectorLabels" . | nindent 8 }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "product-bulk-creator.serviceAccountName" . }}
      restartPolicy: Never
      containers:
      - name: product-creator
        image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
        imagePullPolicy: {{ .Values.image.pullPolicy }}
        command: ["/bin/sh"]
        args:
          - -c
          - |
            # Install required packages
            apk add --no-cache bash curl jq bc python3

            # Copy scripts from ConfigMap
            cp /config-scripts/test-save-products.sh /scripts/test-save-products.sh
            cp /config-scripts/run-parallel.sh /scripts/run-parallel.sh
            chmod +x /scripts/*.sh

            # Execute parallel script
            /scripts/run-parallel.sh
        env:
        - name: GRAPHQL_ENDPOINT
          value: {{ .Values.env.graphqlEndpoint | quote }}
        - name: API_TOKEN
          valueFrom:
            secretKeyRef:
              name: {{ include "product-bulk-creator.fullname" . }}-secret
              key: api-token
        - name: PRODUCT_COUNT
          value: {{ .Values.env.productCount | quote }}
        - name: PARALLEL_COUNT
          value: {{ .Values.env.parallelCount | quote }}
        resources:
          {{- toYaml .Values.resources | nindent 12 }}
        volumeMounts:
        - name: scripts
          mountPath: /config-scripts
        - name: tmp
          mountPath: /tmp
        - name: workdir
          mountPath: /scripts
      volumes:
      - name: scripts
        configMap:
          name: {{ include "product-bulk-creator.fullname" . }}-config
          defaultMode: 0755
      - name: tmp
        emptyDir: {}
      - name: workdir
        emptyDir: {}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}

